cat >> test/app.test.ts <<'EOF'

const patch = (token: string, id: number | string, body: unknown) =>
  fetch(`${base}/products/${id}`, {
    method: "PATCH",
    headers: { ...as(token), "content-type": "application/json" },
    body: JSON.stringify(body),
  });

test("admin can set a product discount", async () => {
  const res = await patch("admin-token", 1, { discountPercent: 25 });
  assert.equal(res.status, 200);
  assert.equal((await res.json()).discount_percent, 25);
  const products = await (await fetch(`${base}/products`, { headers: as("alice-token") })).json();
  assert.equal(products.find((p: { id: number }) => p.id === 1).discount_percent, 25);
});

test("non-admin cannot set a discount", async () => {
  const res = await patch("alice-token", 1, { discountPercent: 50 });
  assert.equal(res.status, 403);
});

test("discount rejects bad input and unknown products", async () => {
  for (const v of [-1, 101, 10.5, "10", null, undefined]) {
    assert.equal((await patch("admin-token", 1, { discountPercent: v })).status, 400);
  }
  assert.equal((await patch("admin-token", "abc", { discountPercent: 5 })).status, 404);
  assert.equal((await patch("admin-token", 99999, { discountPercent: 5 })).status, 404);
});
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -25

